"""
    Round up values - mappable function for pandas processing
    NOTES:
     - credit: Alok Singhal
    """
def myround(
    x: Any, base: Any = 5, integer: Any = True, round_up: Any = False
) -> object {
    rounded = base * round((float(x) / base));
    if round_up {
        if (rounded < x) {
            rounded += base;
        }
    }
    if integer {
        return int(rounded);
    } else {
        return rounded;
    }
}

